update public.questions set explanation = '1 km/h = 1000 m ÷ 3600 s = 1/3.6 m/s, so divide by 3.6: 72 ÷ 3.6 = 20 m/s.' where id = 'c8ad0ffd-3d87-4852-9849-03ba21bd2683';
update public.questions set explanation = 'Reading = main scale + (circular scale × 0.01 mm) = 4.5 + (23 × 0.01) = 4.73 mm.' where id = 'a6493107-4bd8-49d6-b170-dd7e422df732';
update public.questions set explanation = 'p = mv = 10 × 4 = 40 kg·m/s, in the direction of travel.' where id = '362c7f9b-18cf-4a85-adae-ed879c03f268';
update public.questions set explanation = 'Friction in the brakes does work against the motion, so the kinetic energy becomes internal (thermal) energy in the brakes and tyres.' where id = 'fd1f6437-8a41-4c95-a9b1-497b4e3e4170';
update public.questions set explanation = 'It floats when its density is less than the liquid''s — the upthrust (weight of fluid displaced) equals its weight before the object is fully submerged.' where id = '681903da-2cc0-4495-879a-8dc46886dd49';
update public.questions set explanation = 'Total distance = 150 + 90 = 240 km in 3 h, so average speed = 240 ÷ 3 = 80 km/h. Never average the two speeds directly.' where id = 'b8be47ac-3ff9-429a-b172-9305f5e8ffb4';
update public.questions set explanation = 'p = ρgh, so it depends on the liquid''s density, g and the depth — not on the shape or volume of the container.' where id = '3b0fcdaa-f0c6-472e-9a98-0e7dc08567ed';
update public.questions set explanation = 'In a transverse wave (light, water ripples) particles oscillate perpendicular to the direction of energy transfer; in a longitudinal wave (sound) they vibrate along it.' where id = 'fd42ef07-f49e-47ff-b239-4ce3b430f676';
update public.questions set explanation = 'Gamma is electromagnetic radiation with no charge and effectively no mass, which is why it is the most penetrating ionising radiation.' where id = '15c47fe5-b036-43bc-a4ca-a8451d7d39f1';
update public.questions set explanation = 'Its magnetism can be switched off by breaking the current and its strength can be varied — a permanent magnet cannot do either.' where id = 'c7a98280-0134-4bea-9cfb-faaba774a465';
update public.questions set explanation = 'Stars fuse hydrogen nuclei into helium in their cores; the small mass lost is released as energy (E = mc²).' where id = '3b18f17f-3353-41d5-b7ac-f6efaa48c6fa';
update public.questions set explanation = 'Gravity acts at a distance through a field. Friction, air resistance and the normal contact force act only when surfaces touch.' where id = 'b150b1c4-1311-4428-91b9-93eb2bfd24a6';
update public.questions set explanation = 'a = Δv/Δt = (0 − 20) ÷ 4 = −5 m/s², so the deceleration is 5 m/s².' where id = 'cb692a8b-f665-4c63-9a73-d31e0773ece8';
update public.questions set explanation = 'Newton''s first law: zero resultant force means no acceleration, so a stationary object stays at rest.' where id = 'f563d490-fc53-4b56-a2ae-e7b4a6693a76';
update public.questions set explanation = 'W = F × d = 20 × 5 = 100 J (the force must be along the direction of motion).' where id = '3c5d3c43-fb9b-4a11-9999-f90ace4b339b';
update public.questions set explanation = 'KE = ½mv² = ½ × 2 × 3² = 9 J.' where id = '13758611-5631-4ef3-bfc8-9126ba69eb7c';
update public.questions set explanation = 'ΔGPE = mgh = 5 × 10 × 2 = 100 J.' where id = 'd3f5b10e-9208-4bd3-a7b5-2708ada9bc5e';
update public.questions set explanation = 'Efficiency = useful output ÷ total input = 350 ÷ 500 = 0.70 = 70%.' where id = 'a3eb1809-3e09-4cc9-89fb-817d46bb0233';
update public.questions set explanation = 'Work done = mgh = 10 × 10 × 4 = 400 J, so P = W ÷ t = 400 ÷ 8 = 50 W.' where id = 'a5bc8537-62a7-4376-a8b6-735c10c71b23';
update public.questions set explanation = 'Stretching stores elastic potential energy; releasing the band returns it as kinetic energy.' where id = '295c0433-7e44-457f-88a4-8b9953943ea2';
update public.questions set explanation = 'That is the principle of conservation of energy: energy is only transferred or transformed, never created or destroyed.' where id = '17993136-803f-40e4-93e4-5736e9247b02';
update public.questions set explanation = 'Power is the rate of doing work (or of transferring energy): P = W ÷ t, measured in watts (J/s).' where id = '46cfa928-85e1-4f63-80fe-7f5d931ed167';
update public.questions set explanation = 'Momentum is conserved: 60 × 2 = 120 = 40 × v, so v = 3 m/s in the opposite direction.' where id = '9a185013-1dc5-4943-92e8-c632aea80fe9';
update public.questions set explanation = 'Q = mcΔθ = 2 × 4200 × (80 − 20) = 2 × 4200 × 60 = 504 000 J.' where id = 'a9f3bead-f690-46d0-a9b0-49f6cecac45b';
update public.questions set explanation = 'They increase the time taken to stop, so the same change in momentum needs a smaller force (F = Δp/Δt).' where id = '03a183c7-154f-495e-89f8-96646f1b75fc';
update public.questions set explanation = 'KE ∝ v², so doubling the speed multiplies the kinetic energy by 2² = 4.' where id = 'ef141632-fbc3-4f40-988d-1e11bf8dde44';
update public.questions set explanation = 'p = F ÷ A = 50 ÷ 0.5 = 100 Pa.' where id = 'a65a144d-97b8-4327-a6f1-53dd14a4eab7';
update public.questions set explanation = 'pV is constant (Boyle''s law), so halving the volume at constant temperature doubles the pressure.' where id = '760bdd29-0f17-448c-a07f-2277da1577e3';
update public.questions set explanation = '1 kg/m³ = 0.001 g/cm³, so 1000 kg/m³ = 1 g/cm³ — the density of water.' where id = '01f97499-07cc-4f57-a0c1-24f3538741f6';
update public.questions set explanation = 'ρ = m ÷ V = 200 ÷ 50 = 4 g/cm³.' where id = '0c46bb6d-11d8-439b-b4fc-2c6cc02fa7fe';
update public.questions set explanation = 'p = ρgh = 1000 × 10 × 5 = 50 000 Pa.' where id = '66a04e92-4fa8-4599-a0e3-df5f27c12151';
update public.questions set explanation = 'The same force over a much smaller contact area gives a much larger pressure, so the blade cuts instead of crushing.' where id = '836c8398-5a83-4f17-8ac0-ea43b2f095aa';
update public.questions set explanation = 'Q = mL = 3 × 334 000 = 1 002 000 J; the temperature stays at 0 °C throughout melting.' where id = 'f25cda23-21ce-4cb5-88e8-3a95276684cd';
update public.questions set explanation = 'Energy goes in as latent heat to break the bonds of the lattice, so internal energy increases even though the temperature stays at 0 °C.' where id = '112afadb-de64-43f5-830d-68ad7c5cb68f';
update public.questions set explanation = 'Sound is longitudinal — particles vibrate along the direction the wave travels, forming compressions and rarefactions.' where id = '74b79799-ff0c-4353-88ff-d80f8660e810';
update public.questions set explanation = 'λ = v ÷ f = 600 ÷ 200 = 3 m.' where id = '88e4f70a-e8db-4dbb-a906-f27bbb41e9d1';
update public.questions set explanation = 'For parallel resistors 1/R = 1/10 + 1/10 = 2/10, so R = 5 Ω (less than either resistor).' where id = '505f853e-b5aa-42e7-944f-4f4f8891b473';
update public.questions set explanation = 'A light-dependent resistor''s resistance falls as light intensity rises, which is how it switches a light-sensing circuit.' where id = '02383b63-2e36-4436-bee7-47bf902c5dca';
update public.questions set explanation = 'A generator converts kinetic energy to electrical energy by electromagnetic induction; a motor does the reverse.' where id = '85644526-6bda-4572-8ab2-490d6dbd7713';
update public.questions set explanation = 'Uranium has Z = 92, so 92 protons; neutrons = 235 − 92 = 143.' where id = 'a07afcac-52ca-4414-b78a-21e13581b81f';
update public.questions set explanation = 'Isotopes of an element have the same number of protons (the same Z) but different numbers of neutrons.' where id = '9e74f51d-e026-4ccd-8935-21ce28d95e28';
update public.questions set explanation = 'At full moon the Sun, Earth and Moon are in line with the Earth in the middle, so the whole sunlit face of the Moon is visible.' where id = 'ff4fb99f-6b18-4ac8-9747-439c1265cdb5';
update public.questions set explanation = 'Velocity has both magnitude and direction, so it is a vector; speed, distance and mass are scalars.' where id = '6d98e429-e1e4-41eb-bb0e-901c124a5fa3';
update public.questions set explanation = 'Leading zeros are not significant; the 5, 4 and the trailing 0 after the decimal point are, so 3 significant figures.' where id = 'e2a38899-e429-4966-9478-631bb2e1219d';
update public.questions set explanation = 'W = mg = 5 × 10 = 50 N (weight is a force, in newtons).' where id = '40ef2485-6635-49c5-a22b-c6a6b3c0fcea';
update public.questions set explanation = 'At terminal velocity air resistance has grown until it equals the weight, so the resultant force is zero and the acceleration is zero.' where id = '266386ff-e68b-4857-9ef7-dcbe36a42b74';
update public.questions set explanation = 'For a fixed mass of gas at constant temperature, reducing the volume increases the collision rate with the walls, so the pressure rises.' where id = '4c157853-83e3-42ce-99b1-168da67d4052';
update public.questions set explanation = 'V ∝ T with T measured in kelvin: heating a gas at constant pressure makes it expand so that V/T stays constant.' where id = '3c013f1c-2bd7-432a-bc66-60c46505928e';
update public.questions set explanation = 'Gas molecules move in continuous random straight lines, changing direction only when they collide with each other or with the walls.' where id = '0605bf2a-6d81-4ede-85a6-ce2fd2887701';
update public.questions set explanation = 'Strong hydrogen bonds between water molecules take a lot of energy to overcome, giving water a large specific heat capacity (4200 J/kg °C).' where id = '071ebbe8-0ca0-4e93-ba1f-23eb0165537a';
update public.questions set explanation = 'Sound needs a medium to carry compressions; the vacuum of space has no particles to vibrate.' where id = '7a09b74d-5305-480b-87a9-36c230a6aafd';
update public.questions set explanation = 'v = fλ = 50 × 4 = 200 m/s.' where id = '6b42b07d-ce11-4673-9c97-eb8d3bef177c';
update public.questions set explanation = 'Gamma rays have the shortest wavelength and highest frequency (and most energy) of the electromagnetic spectrum.' where id = '7ef9bcb7-00f9-4e04-8201-6ffeb7d9ae8e';
update public.questions set explanation = 'T(K) = θ(°C) + 273 = 25 + 273 = 298 K.' where id = 'a14e5d9a-ec48-45eb-b50d-60ac4bb4e212';
update public.questions set explanation = 'Glass is optically denser, so light slows down and refracts towards the normal; on leaving it speeds up and bends away from the normal.' where id = 'd4f82168-924b-4649-af35-e3b3bcb1fc3c';
update public.questions set explanation = 'Violet has the highest frequency and so the highest refractive index in glass, so it is deviated most (red least).' where id = '90b11265-23b4-4b0f-bdea-5c533f44ef60';
update public.questions set explanation = 'Every electromagnetic wave travels at 3 × 10⁸ m/s in a vacuum.' where id = '66793c9b-c426-4b01-b85b-5d7ca44d21c1';
update public.questions set explanation = 'In series R_total = 4 + 4 + 4 = 12 Ω, because the same current flows through each resistor.' where id = '7ff9a0b9-7a10-4ed9-95b3-634a21a11fac';
update public.questions set explanation = 'The sound travels to the cliff and back in 0.4 s, so d = vt ÷ 2 = 340 × 0.4 ÷ 2 = 68 m.' where id = '4822b3ea-083d-44e2-9e01-d30a9872158d';
update public.questions set explanation = 'Q = It, so I = Q ÷ t = 60 C ÷ 120 s = 0.5 A (convert the minutes to seconds first).' where id = 'f9b022eb-b786-4961-81de-6d9ec00e5649';
