update public.questions set explanation = 'Energy = power × time = 0.1 kW × 3 h = 0.3 kWh (use kW and hours to get kWh).' where id = 'ccf4d9a6-b3d3-499f-908a-e7c7448a2b7e';
update public.questions set explanation = 'P = VI = 10 × 2 = 20 W.' where id = '2e88ba2c-6b40-4537-8a8e-3fdd5ce572e3';
update public.questions set explanation = 'A copper core is not ferromagnetic. More turns, a larger current and an iron core all make the field stronger.' where id = 'ef161a83-cc09-43a8-b4a1-6513eb72f00b';
update public.questions set explanation = 'A motor uses the force on a current-carrying coil in a magnetic field to produce rotation.' where id = '9b1791f9-e936-4fab-a1b4-d2eaeda75d7a';
update public.questions set explanation = 'Mains is alternating current: the voltage and current reverse direction many times a second (50 Hz in the UK).' where id = 'a4eb8844-e802-4864-9bd6-4091527a578d';
update public.questions set explanation = 'Like poles repel, so two north poles push apart; opposite poles attract.' where id = '4cfd59fe-996b-40b4-b259-48af41568bbf';
