update public.questions set explanation = 'The Earth behaves like a bar magnet: its magnetic field makes a freely suspended compass needle line up north–south.' where id = '226b01ce-412a-4e41-b945-7229c8d7d176';
update public.questions set explanation = 'Alpha radiation is the least penetrating — a sheet of paper or a few centimetres of air stops it.' where id = 'bbe9cf23-9b42-4eae-b2c6-7dddd49dfd52';
update public.questions set explanation = 'In beta decay a neutron changes into a proton plus an emitted electron (the beta particle), so the proton number rises by 1.' where id = '51d417ec-f65c-4fbc-b561-9d89345d5d28';
update public.questions set explanation = 'Each half-life halves the count rate: 800 → 400 → 200 → 100 Bq.' where id = '5915cc88-f6dd-48b8-a972-d07c4f74e066';
update public.questions set explanation = 'Only thick lead or many centimetres of concrete absorb gamma; paper and aluminium foil are not enough.' where id = '5ae5cdc2-f6eb-433d-ab7a-b604b27b6aed';
update public.questions set explanation = 'Fission splits a large nucleus (usually after it absorbs a neutron) into smaller nuclei, releasing energy.' where id = '01e4cab2-d0f2-4d01-9c00-3a466eb8d8a9';
update public.questions set explanation = 'Carbon-14 has a half-life of about 5730 years, which is why it can date material up to tens of thousands of years old.' where id = '63322afa-e2be-4ffe-b00d-7436693f4ad9';
update public.questions set explanation = 'Fusion needs a very high temperature (millions of °C) and pressure so that nuclei overcome their mutual repulsion and join.' where id = 'de503643-fbbc-4eda-86fc-06e8a27cba8b';
update public.questions set explanation = 'The Earth''s axis is tilted at about 23.5°, so each hemisphere gets more direct sunlight and longer days during its summer.' where id = '7fd37311-4928-4dd7-af66-e287bca510e0';
update public.questions set explanation = 'The Earth rotates once on its axis every 24 hours, which is what produces day and night.' where id = 'ee8c0427-2665-4001-9b82-0c1e1c6695cf';
update public.questions set explanation = 'Galaxies'' spectral lines are shifted to longer wavelengths in proportion to their distance — evidence that the Universe is expanding.' where id = 'a213274e-a7c2-46b0-a115-cb64f9871115';
update public.questions set explanation = 'Venus is the hottest planet: its thick carbon-dioxide atmosphere traps heat in a runaway greenhouse effect, even though Mercury is nearer the Sun.' where id = 'e3a66e8f-6200-404b-9ec4-b2f0ab8ea6d2';
update public.questions set explanation = 'A solar eclipse happens at new moon, when the Moon passes directly between the Sun and the Earth.' where id = 'b32686a4-200e-4357-9a2a-0aec84cb4097';
update public.questions set explanation = 'There are 8 planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune.' where id = 'db9a0cab-2119-4d1c-934c-60004aedade6';
